mapper.select:
SELECT
    sum( order_payment_amount ) AS amount
FROM
    pay_consume_trade
where
    trade_is_paid IN ( 3012, 3013 )

        AND trade_paid_time BETWEEN #{startTime} AND #{endTime}

    AND trade_type_id IN ( 1201, 1214 )

        AND buyer_id = #{buyerId}


        AND chain_id = #{chainId}


        AND store_id = #{storeId}
